<?php
declare(strict_types=1);
namespace Cbt\Core;
final class Router { private array $routes=[]; public function add(string $method,string $pattern,callable $handler,array $middleware=[]):void{$this->routes[]=[$method,$pattern,$handler,$middleware];} public function get(string$p,callable$h,array$m=[]):void{$this->add('GET',$p,$h,$m);} public function post(string$p,callable$h,array$m=[]):void{$this->add('POST',$p,$h,$m);} public function put(string$p,callable$h,array$m=[]):void{$this->add('PUT',$p,$h,$m);} public function patch(string$p,callable$h,array$m=[]):void{$this->add('PATCH',$p,$h,$m);} public function delete(string$p,callable$h,array$m=[]):void{$this->add('DELETE',$p,$h,$m);} public function dispatch(Request$r):Response{foreach($this->routes as[$method,$pattern,$handler,$middleware]){if($method!==$r->method)continue;$regex='#^'.preg_replace('/\{([A-Za-z][A-Za-z0-9_]*)\}/','(?P<$1>[A-Za-z0-9_-]+)',$pattern).'$#';if(!preg_match($regex,$r->path,$matches))continue;foreach(array_filter($matches,'is_string',ARRAY_FILTER_USE_KEY)as$k=>$v)$r->attributes[$k]=$v;$next=fn(Request$q):Response=>$handler($q);foreach(array_reverse($middleware)as$mw){$previous=$next;$next=fn(Request$q):Response=>$mw($q,$previous);}return$next($r);}return Response::error('Endpoint tidak ditemukan.',404);} }
